//! Common exact HTML metadata survives native import and promotion.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><div id=mount></div><span class='A�z'></span></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn html_metadata_materialization_import_preserves_exact_reflections_tokens_and_source(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=document.implementation.createHTMLDocument('source'),source=owner.createElement('div'),names=['class','title','lang','dir'];owner.body.appendChild(source);for(var i=0;i<names.length;i++)source.setAttribute(names[i],'A\ud800z');var copy=document.importNode(source,true);document.getElementById('mount').appendChild(copy);for(var i=0;i<names.length;i++){var a=source.getAttributeNode(names[i]),b=copy.getAttributeNode(names[i]);if(a===b||a.ownerDocument!==owner||b.ownerDocument!==document||a.ownerElement!==source||b.ownerElement!==copy||b.value!=='A\ud800z')throw 'independent metadata';}if(copy.className!=='A\ud800z'||copy.title!=='A\ud800z'||copy.lang!=='A\ud800z'||copy.dir!==''||copy.classList.length!==1||copy.classList[0]!=='A\ud800z'||copy.classList.contains('A�z')||document.getElementsByClassName('A\ud800z')[0]!==copy||copy.matches('.A�z')||!copy.matches(':not(.A�z)'))throw 'actual metadata consumers';copy.classList.add('plain');copy.title='B\udfffz';copy.lang='C\udfffz';copy.dir='RTL';if(source.getAttribute('class')!=='A\ud800z'||source.title!=='A\ud800z'||source.lang!=='A\ud800z'||source.getAttribute('dir')!=='A\ud800z'||copy.dir!=='rtl'||!copy.classList.contains('A\ud800z')||!copy.matches('.plain'))throw 'independent replacements';
"#);}
#[test]
fn html_metadata_materialization_promotion_preserves_attr_identity_and_observation(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var t=document.createElement('template');t.innerHTML='<span class=seed title=seed lang=seed dir=ltr>held</span>';var source=t.content.firstChild,names=['class','title','lang','dir'],attrs=[];for(var i=0;i<names.length;i++){var a=source.getAttributeNode(names[i]);a.value='B\udfffz';attrs.push(a);}var live=document.getElementsByClassName('B\udfffz'),mount=document.getElementById('mount');mount.appendChild(t.content);for(var i=0;i<names.length;i++)if(source.getAttributeNode(names[i])!==attrs[i]||attrs[i].ownerDocument!==document||attrs[i].ownerElement!==source||attrs[i].value!=='B\udfffz')throw 'promoted Attr';if(live[0]!==source||source.title!=='B\udfffz'||source.lang!=='B\udfffz'||source.dir!==''||source.matches('.B�z')||!source.classList.contains('B\udfffz'))throw 'promoted consumers';var watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,attributeOldValue:true});source.className='fresh';source.title='fresh';source.lang='fresh';source.removeAttribute('dir');var records=watch.takeRecords();if(records.length!==4||live.length||source.dir!==''||attrs[3].ownerElement!==null)throw 'live mutation';for(var i=0;i<records.length;i++)if(records[i].oldValue!=='B\udfffz')throw 'exact old values';
"#);}
#[test]
fn html_metadata_materialization_native_control_import_retains_real_value_and_metadata(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=document.implementation.createHTMLDocument('source'),source=owner.createElement('input');source.setAttribute('name','q');source.setAttribute('value','ready');var names=['class','title','lang','dir'];for(var i=0;i<names.length;i++)source.setAttribute(names[i],'A\ud800z');var copy=document.importNode(source,true);document.getElementById('mount').appendChild(copy);if(copy.value!=='ready'||copy.name!=='q'||copy.form!==null||copy.className!=='A\ud800z'||copy.title!=='A\ud800z'||copy.lang!=='A\ud800z'||copy.dir!==''||!copy.classList.contains('A\ud800z')||copy.matches('.A�z'))throw 'native imported control';copy.value='edited';if(copy.value!=='edited'||source.getAttribute('value')!=='ready'||copy.getAttribute('name')!=='q')throw 'real native control';
"#);}

#[test]
fn html_metadata_materialization_template_copy_keeps_raw_contents_inert_until_promoted(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var t=document.createElement('template');t.innerHTML='<span class=seed title=seed lang=seed dir=ltr>held</span>';var original=t.content.firstChild,names=['class','title','lang','dir'];for(var i=0;i<names.length;i++)original.setAttribute(names[i],'B\udfffz');var c=document.importNode(t,true),copy=c.content.firstChild;if(copy===original||copy.ownerDocument===document||copy.getAttribute('class')!==original.getAttribute('class')||copy.title!==original.title||copy.lang!==original.lang||copy.getAttribute('dir')!==original.getAttribute('dir')||document.getElementsByClassName('B\udfffz').length)throw 'inert metadata copy';document.getElementById('mount').appendChild(c.content);if(copy.ownerDocument!==document||original.ownerDocument===document||document.getElementsByClassName('B\udfffz')[0]!==copy)throw 'promoted copied metadata';copy.className='fresh';if(original.getAttribute('class')!=='B\udfffz'||document.getElementsByClassName('B\udfffz').length)throw 'independent copy';
"#);}
#[test]
fn html_metadata_materialization_import_and_promotion_resource_refusal_is_atomic_and_recovers(){
 for promote in [false,true]{let(mut d,mut forms,mut page)=fixture();run(&mut d,&mut forms,&mut page,r#"var owner=document.implementation.createHTMLDocument('source'),source=owner.createElement('div'),names=['class','title','lang','dir'];owner.body.appendChild(source);var t=document.createElement('template');t.innerHTML='<span class=seed title=seed lang=seed dir=ltr>held</span>';var parked=t.content.firstChild,oldOwner=parked.ownerDocument,attrs=[];for(var i=0;i<names.length;i++){source.setAttribute(names[i],'long A\ud800z');var a=parked.getAttributeNode(names[i]);a.value='long B\udfffz';attrs.push(a);}var mount=document.getElementById('mount'),watch=new MutationObserver(function(){});watch.observe(mount,{childList:true});"#);page.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(page.state.retained,page.state.dom_commits,page.state.attributes.len());let limit=page.state.retained_limit;
  for mode in 0..3{page.begin_job();match mode{0=>page.state.host_work=0,1=>page.state.copy_work=0,_=>page.state.retained_limit=0};let source=if promote{"mount.appendChild(t.content);"}else{"document.importNode(source,true);"};let error=page.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut forms,state:&mut page.state}).unwrap_err();assert!(error.contains("work")||error.contains("allowance")||error.contains("limit"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((page.state.retained,page.state.dom_commits,page.state.attributes.len()),state);page.state.retained_limit=limit;}
  page.begin_job();run(&mut d,&mut forms,&mut page,r#"if(source.parentNode!==owner.body||parked.parentNode!==t.content||parked.ownerDocument!==oldOwner||watch.takeRecords().length||mount.childNodes.length)throw 'refusal publication';for(var i=0;i<names.length;i++)if(source.getAttribute(names[i])!=='long A\ud800z'||parked.getAttributeNode(names[i])!==attrs[i]||attrs[i].ownerDocument!==oldOwner||attrs[i].value!=='long B\udfffz')throw 'refused attributes';var copy=document.importNode(source,true);mount.appendChild(copy);mount.appendChild(t.content);if(copy.title!=='long A\ud800z'||parked.lang!=='long B\udfffz'||document.getElementsByClassName('B\udfffz')[0]!==parked||attrs[0].ownerDocument!==document)throw 'fresh metadata recovery';"#);
 }
}
#[test]
fn html_metadata_materialization_foreign_namespaced_and_active_attributes_remain_guarded(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=document.implementation.createHTMLDocument('source'),foreign=owner.createElementNS('http://www.w3.org/2000/svg','g'),qualified=owner.createElement('span'),active=owner.createElement('a');foreign.setAttribute('class','A\ud800z');qualified.setAttributeNS('urn:attr','class','A\ud800z');active.setAttribute('href','A\ud800z');
"#);p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());for source in ["document.importNode(foreign,true);","document.importNode(qualified,true);","document.importNode(active,true);"]{p.begin_job();assert!(p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err(),"{source}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);}run(&mut d,&mut f,&mut p,r#"if(foreign.ownerDocument!==owner||foreign.getAttribute('class')!=='A\ud800z'||qualified.getAttributeNS('urn:attr','class')!=='A\ud800z'||active.getAttribute('href')!=='A\ud800z')throw 'protected metadata';var good=owner.createElement('span');good.title='B\udfffz';var copy=document.importNode(good,true);if(copy.title!==good.title||copy.ownerDocument!==document)throw 'fresh recovery';"#);}
